import sys, json
sys.path.insert(0, '/workspace/tests')
from harness import BASE_CFG, cfg, trace, req, run, is_invalid

def dg(t, size, packets): return {"t":t,"op":"datagram","bytes":size,"packets":packets}
def pkt(level, pn, frames, auth=True): return {"level":level,"pn":pn,"auth":auth,"frames":frames}
def key(t, level, action): return {"t":t,"op":"key","level":level,"action":action}
def tick(t): return {"t":t,"op":"tick"}
def F(ty, **kw):
    d = {"type": ty}
    d.update(kw)
    return d

def PK(got, i=0):
    return [(p["event"], p["packet"], p["status"], p["reason"], p["at_ms"], p["frame"])
            for p in got["results"][i]["packets"]]

def CONN(got, i=0):
    c = got["results"][i]["connection"]
    return (c["state"], c["code"], c["at_ms"], c["source"], c["peer_code"], c["last_activity_ms"])

def KEYS(got, i=0):
    k = got["results"][i]["keys"]
    return (k["I"], k["H"], k["Z"], k["A"])

def ST(got, i=0):
    return [(s["id"], s["highest"], s["final_size"], s["reset"], s["stopped"], s["delivered_hex"])
            for s in got["results"][i]["streams"]]

def CR(got, i=0):
    return [(c["level"], c["highest"], c["contiguous_hex"]) for c in got["results"][i]["crypto"]]

def RT(got, i=0):
    return got["results"][i]["received_total"]

def one(events, **kw):
    got = run(req([trace("t", events, **kw)]))
    if got is None or is_invalid(got):
        return {"INVALID": True}
    return got

def view(got, i=0):
    r = got["results"][i]
    return {"pk": PK(got, i), "conn": CONN(got, i), "keys": KEYS(got, i),
            "rt": RT(got, i), "st": ST(got, i), "cr": CR(got, i)}

def showview(name, got, i=0):
    print(name)
    print("  ", json.dumps(view(got, i)))
